    public void calculateSolarPosition_CalculateForNegativeLatitude_ReturnsIncorrectResult() {
        // arrange
        ZonedDateTime date = ZonedDateTime.of(2022, 1, 1, 12, 0, 0, ZoneOffset.UTC);
        double latitude = -52.5236;
        double longitude = 13.4050;
        double deltaT = 10.5;

        // act
        AzimuthZenithAngle azimuthZenithAngle = Grena3.calculateSolarPosition(date, latitude, longitude, deltaT);

        // assert
        assertEquals(-90.1234, azimuthZenithAngle.getAzimuth(), 0.01);
